// bench-strategy: variant-ladder-jsx-components
// cn — button-variants-nested. Three modules, each exporting a JSX COMPONENT:
// Button, GhostButton extending it, GhostPrimaryButton extending that. The module
// API is the component, so every lane wraps — the page only renders the leaf.
// Paired with button-variants (same ladder as style values merged at one element).
import React from "react";
import { GhostPrimaryButton } from "./ghost-primary-button";

// Three levels, so the merge runs THREE times per render — once per wrapper.
export default (i: number) => <GhostPrimaryButton>{i}</GhostPrimaryButton>;

import React from "react";
import { cn } from "cn";

const BASE = "inline-flex items-center justify-center gap-1.5 border border-solid border-transparent rounded-md px-4 py-2 text-sm font-semibold cursor-pointer bg-blue-600 text-white";

export const Button = ({ className, children }: { className?: string; children?: React.ReactNode }) => (
  <button className={cn(BASE, className)}>{children}</button>
);

import React from "react";
import { cn } from "cn";
import { Button } from "./button";

const GHOST = "bg-transparent border-gray-300 text-gray-700";

export const GhostButton = ({ className, children }: { className?: string; children?: React.ReactNode }) => (
  <Button className={cn(GHOST, className)}>{children}</Button>
);

import React from "react";
import { cn } from "cn";
import { GhostButton } from "./ghost-button";

const GHOST_PRIMARY = "border-blue-600 text-blue-600";

export const GhostPrimaryButton = ({ className, children }: { className?: string; children?: React.ReactNode }) => (
  <GhostButton className={cn(GHOST_PRIMARY, className)}>{children}</GhostButton>
);

