// bench-strategy: same-as-product-grid-multifile
// cn-solid — multifile-shop. The SAME tile as product-grid (same DOM, same CSS, same
// rendered class lists), laid out the way a design system ships it: shared bundles in
// tokens.ts, a base button in button.ts, and the class lists split by role over layout /
// controls / text. cn concatenates the list on every render; the module split changes
// nothing about that, so this lane should track product-grid.
import { cn } from "cn";
import { BUTTON_BASE } from "./button";
import { FOCUS_RING, TAP_TARGET } from "./tokens";
import { CARD, IMAGE_WRAP, IMAGE_PLACEHOLDER } from "./layout";
import { WISHLIST, WISHLIST_HOVER, ADD_TO_CART, ADD_TO_CART_HOVER, ADD_TO_CART_DISABLED } from "./controls";
import { BADGE, TITLE, RATING, RATING_FILL, PRICE_ROW, OLD_PRICE, NOW_PRICE } from "./text";

interface Product {
  i: number;
  title: string;
  price: number;
  discount: number;
  rating: number;
  inStock: boolean;
  wishlisted: boolean;
}

// The product arrives as an accessor: a dynamic JSX prop compiles to a getter, so
// `p={p()}` would rebuild the object on every read. aria booleans are written as
// explicit "true"/"false" strings so the markup matches the React lanes.
const Tile = (props: { p: () => Product }) => {
  const pct = () => (props.p().rating / 5) * 100 + "%";
  return (
    <li class={CARD}>
      <div class={IMAGE_WRAP}>
        <div aria-hidden="true" class={IMAGE_PLACEHOLDER} />
        {props.p().discount > 0 && (
          <span class={cn(BADGE, props.p().discount >= 30 ? "bg-red-600" : "bg-amber-500")}>
            <span class="sr-only">Reduced by </span>-{props.p().discount}%
          </span>
        )}
        <button
          type="button"
          aria-pressed={props.p().wishlisted ? "true" : "false"}
          aria-label={props.p().wishlisted ? "Remove from wishlist" : "Add to wishlist"}
          class={cn(
            BUTTON_BASE,
            WISHLIST,
            WISHLIST_HOVER,
            FOCUS_RING,
            TAP_TARGET,
            props.p().wishlisted ? "text-red-500" : "text-gray-400",
          )}
        >
          <span aria-hidden="true">♥</span>
        </button>
      </div>
      <h3 class={TITLE}>{props.p().title}</h3>
      <div role="img" aria-label={`Rated ${props.p().rating} out of 5`} class={RATING}>
        <div aria-hidden="true" class={RATING_FILL} style={{ "--pct": pct() }} />
      </div>
      <div class={PRICE_ROW}>
        {props.p().discount > 0 && (
          <span class={OLD_PRICE}>
            <span class="sr-only">Was </span>${(props.p().price * (1 + props.p().discount / 100)).toFixed(2)}
          </span>
        )}
        <span class={NOW_PRICE}>
          {props.p().discount > 0 && <span class="sr-only">Now </span>}${props.p().price.toFixed(2)}
        </span>
      </div>
      <button
        disabled={!props.p().inStock}
        aria-label={props.p().inStock ? `Add ${props.p().title} to cart` : `${props.p().title} is sold out`}
        class={cn(
          BUTTON_BASE,
          ADD_TO_CART,
          ADD_TO_CART_HOVER,
          FOCUS_RING,
          TAP_TARGET,
          !props.p().inStock && ADD_TO_CART_DISABLED,
        )}
      >
        {props.p().inStock ? "Add to cart" : "Sold out"}
      </button>
    </li>
  );
};

export default (i: () => number) => {
  // ONE product built from i with the same per-item formula as every other lane.
  // Cached on the index: the accessor is read many times per render and the formula is
  // the same every time, so rebuilding the object per read would be pure waste.
  let last = NaN;
  let cached!: Product;
  const p = (): Product => {
    const n = i();
    if (n !== last) {
      last = n;
      cached = {
        i: n,
        title: "Product " + n,
        price: (n % 50) + 9.99,
        discount: n % 4 === 0 ? (n % 3 === 0 ? 40 : 20) : 0,
        rating: (n % 5) + 1,
        inStock: n % 7 !== 0,
        wishlisted: n % 6 === 0,
      };
    }
    return cached;
  };
  return <Tile p={p} />;
};

// The base button every tap target is built from — exactly the utilities the wishlist
// and add-to-cart lists both carry in the single-file product-grid, so the rendered
// class set is unchanged and the two cases stay comparable.
export const BUTTON_BASE = "border-none cursor-pointer";

// The two tap targets. Their shared border-none/cursor-pointer now come from the
// imported base button, which the page merges in ahead of these.
export const WISHLIST =
  "absolute top-1.5 right-1.5 rounded-full bg-white/80 text-lg leading-none p-1 transition-colors duration-150 motion-reduce:transition-none";

export const WISHLIST_HOVER = "[@media(hover:hover)]:hover:text-red-500";

export const ADD_TO_CART =
  "mt-auto relative rounded-md px-3 py-2 text-sm leading-[normal] font-semibold text-white bg-blue-600 transition-colors duration-150 motion-reduce:transition-none lg:py-[9px]";

export const ADD_TO_CART_HOVER = "[@media(hover:hover)]:hover:bg-blue-700";

export const ADD_TO_CART_DISABLED = "bg-gray-300 text-gray-500 cursor-not-allowed";

// Structure class lists. Strings only — no JSX use site lives in this module.
export const CARD =
  "flex flex-col [container-type:inline-size] [container-name:tile] border border-solid border-gray-200 rounded-lg p-3 bg-white transition-shadow duration-150 [@media(hover:hover)]:hover:shadow-md motion-reduce:transition-none";

export const IMAGE_WRAP = "relative aspect-square bg-gray-100 rounded-md overflow-hidden";

export const IMAGE_PLACEHOLDER = "absolute inset-0 bg-[linear-gradient(135deg,#f3f4f6_0%,#e5e7eb_100%)]";

// Copy, rating and price class lists. Strings only — no JSX use site lives here.
export const BADGE =
  "absolute top-1.5 left-1.5 rounded px-1.5 py-0.5 text-xs leading-[normal] font-bold text-white";

export const TITLE =
  "mt-2 mb-1 text-sm leading-[normal] font-medium whitespace-nowrap overflow-hidden text-ellipsis lg:text-[15px] [@container_tile_(min-width:240px)]:text-base [@container_tile_(min-width:240px)]:leading-[normal]";

export const RATING = "h-2 rounded bg-gray-200 overflow-hidden";

export const RATING_FILL = "h-full bg-amber-400 w-[var(--pct)]";

export const PRICE_ROW =
  "flex items-baseline gap-1.5 mt-1.5 mb-2.5 [@container_tile_(min-width:240px)]:gap-2.5";

export const OLD_PRICE = "text-xs leading-[normal] text-gray-400 line-through";

export const NOW_PRICE = "text-base leading-[normal] font-bold text-gray-900";

// The design system's shared utility bundles — WCAG 2.5.5 tap target + keyboard focus
// ring. Pulled by the base button, so they cross a module boundary here.
export const TAP_TARGET =
  "before:content-[''] before:absolute before:inset-1/2 before:[translate:-50%_-50%] before:w-full before:h-full " +
  "[@media(hover:none)_and_(pointer:coarse)]:before:min-w-[44px] [@media(hover:none)_and_(pointer:coarse)]:before:min-h-[44px] " +
  "[@media(hover:hover)_and_(pointer:fine)]:before:min-w-[24px] [@media(hover:hover)_and_(pointer:fine)]:before:min-h-[24px]";

export const FOCUS_RING =
  "focus-visible:outline focus-visible:outline-2 focus-visible:outline-blue-600 focus-visible:outline-offset-2";

