// Emotion — btn-variant. Identical CSS to every other lane; the difference is the
// runtime: Emotion resolves these prop-driven rules and injects CSS at render.
// Default-exports a single-instance render(i) (§6); the harness loops it.
// btn-variant varies active/fullWidth/variant by index.
import React from 'react';
import styled from "@emotion/styled";

// `$`-prefixed props are transient (the styled-components convention this shared template
// uses); emotion forwards every prop to the DOM by default, so strip them per component.
const transient = { shouldForwardProp: (p: string) => p[0] !== "$" };

interface P {
  $active?: boolean;
  $fullWidth?: boolean;
  $variant?: 'primary' | 'secondary' | 'ghost';
  children?: React.ReactNode;
}

const Button = styled("button", transient)<P>`
  display:inline-flex;align-items:center;justify-content:center;border-radius:6px;padding:8px 16px;font-size:14px;line-height:20px;font-weight:500;background-color:#2563eb;color:#ffffff;
  ${(p: P) => !p.$active && 'background-color:#d1d5db;color:#6b7280;'}
  ${(p: P) => p.$variant === 'secondary' && 'background-color:#f3f4f6;color:#111827;'}
  ${(p: P) => p.$variant === 'ghost' && 'background-color:transparent;color:#2563eb;'}
  ${(p: P) => p.$fullWidth && 'width:100%;'}
`;

export default (i: number) => {
  const variant = (['primary', 'secondary', 'ghost'] as const)[i % 3];
  return (
    <Button
      $active={i % 4 !== 0}
      $fullWidth={i % 3 === 0}
      $variant={variant}
    >
      {i}
    </Button>
  );
};

// bench-strategy: variant-ladder-jsx-components
// Emotion — button-variants-nested. Three modules, each exporting a JSX COMPONENT:
// Button, GhostButton extending it, GhostPrimaryButton extending that. The module
// API is the component, so every lane wraps — the page only renders the leaf.
// Paired with button-variants (same ladder as style values merged at one element).
import React from "react";
import { GhostPrimaryButton } from "./ghost-primary-button";

export default (i: number) => <GhostPrimaryButton>{i}</GhostPrimaryButton>;

import styled from "@emotion/styled";

export const Button = styled.button`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-width: 1px;
  border-style: solid;
  border-color: transparent;
  border-radius: 6px;
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  cursor: pointer;
  background: #2563eb;
  color: #fff;
`;

import styled from "@emotion/styled";
import { Button } from "./button";

export const GhostButton = styled(Button)`
  background: transparent;
  border-color: #d1d5db;
  color: #374151;
`;

import styled from "@emotion/styled";
import { GhostButton } from "./ghost-button";

export const GhostPrimaryButton = styled(GhostButton)`
  border-color: #2563eb;
  color: #2563eb;
`;

// bench-strategy: variant-ladder-style-values
// Emotion — button-variants. Three modules, each exporting a STYLE VALUE (not a
// component): base button, ghost override, ghost-primary override. index.tsx
// merges all three onto ONE element, which is how this library composes styles.
// Paired with button-variants-nested, which ships the same ladder as a JSX
// component API — the pair prices the API shape, not the file layout (both split).
import React from "react";
import styled from "@emotion/styled";
import { button } from "./button";
import { ghostButton } from "./ghost-button";
import { ghostPrimaryButton } from "./ghost-primary-button";

// One styled component, three interpolated fragments — the runtime serialises the
// ladder once per class, not once per level per render.
const GhostPrimaryButton = styled.button`
  ${button};
  ${ghostButton};
  ${ghostPrimaryButton};
`;

export default (i: number) => <GhostPrimaryButton>{i}</GhostPrimaryButton>;

import { css } from "@emotion/react";

export const button = css`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-width: 1px;
  border-style: solid;
  border-color: transparent;
  border-radius: 6px;
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  cursor: pointer;
  background: #2563eb;
  color: #fff;
`;

import { css } from "@emotion/react";

export const ghostButton = css`
  background: transparent;
  border-color: #d1d5db;
  color: #374151;
`;

import { css } from "@emotion/react";

export const ghostPrimaryButton = css`
  border-color: #2563eb;
  color: #2563eb;
`;

// bench-strategy: compose-depth
// Emotion — compose-1, the depth-sweep control. ONE styled component carrying only
// the compose-3 base-level styles: no styled(styled) chain. Default-exports a
// single-instance render(i) (§6); the harness loops it.
import React from 'react';
import styled from "@emotion/styled";

// `$`-prefixed props are transient (the styled-components convention this shared template
// uses); emotion forwards every prop to the DOM by default, so strip them per component.
const transient = { shouldForwardProp: (p: string) => p[0] !== "$" };

