// bench-strategy: same-as-product-grid-multifile
// Panda (style props) — multifile-shop. The SAME tile as product-grid (same DOM, same
// CSS, same product data), laid out the way a design system ships it: shared fragments
// in tokens.ts, a base button in button.ts, and the primitives split by role over
// layout / controls / text. Panda resolves style props at render, so file layout costs
// it nothing.
// @ts-nocheck
import React, { type FunctionComponent } from "react";
import { styled } from "styled-system/jsx";
import { buttonBase } from "./button";
import { srOnly, minTargetSize, focusRing } from "./tokens";
import { grid, gridCss, card, cardCss, imageWrap, imagePlaceholder } from "./layout";
import { wishlist, wishlistCss, addToCart, addToCartCss } from "./controls";
import { badge, title, titleCss, rating, ratingFill, priceRow, priceRowCss, oldPrice, nowPrice } from "./text";

interface Product {
  i: number;
  title: string;
  price: number;
  discount: number;
  rating: number;
  inStock: boolean;
  wishlisted: boolean;
}

const Tile: FunctionComponent<{ p: Product }> = ({ p }) => (
  <styled.li {...card} css={cardCss}>
    <styled.div {...imageWrap}>
      <styled.div aria-hidden="true" {...imagePlaceholder} />
      {p.discount > 0 && (
        <styled.span {...badge} background={p.discount >= 30 ? "#dc2626" : "#f59e0b"}>
          <styled.span {...srOnly}>Reduced by </styled.span>-{p.discount}%
        </styled.span>
      )}
      <styled.button
        type="button"
        aria-pressed={p.wishlisted}
        aria-label={p.wishlisted ? "Remove from wishlist" : "Add to wishlist"}
        {...buttonBase}
        {...wishlist}
        css={[wishlistCss, focusRing, minTargetSize]}
        color={p.wishlisted ? "#ef4444" : "#9ca3af"}
      >
        <span aria-hidden="true">♥</span>
      </styled.button>
    </styled.div>
    <styled.h3 {...title} css={titleCss}>{p.title}</styled.h3>
    <styled.div role="img" aria-label={`Rated ${p.rating} out of 5`} {...rating}>
      <styled.div
        aria-hidden="true"
        {...ratingFill}
        style={{ width: (p.rating / 5) * 100 + "%" }}
      />
    </styled.div>
    <styled.div {...priceRow} css={priceRowCss}>
      {p.discount > 0 && (
        <styled.span {...oldPrice}>
          <styled.span {...srOnly}>Was </styled.span>${(p.price * (1 + p.discount / 100)).toFixed(2)}
        </styled.span>
      )}
      <styled.span {...nowPrice}>
        {p.discount > 0 && <styled.span {...srOnly}>Now </styled.span>}${p.price.toFixed(2)}
      </styled.span>
    </styled.div>
    <styled.button
      disabled={!p.inStock}
      aria-label={p.inStock ? `Add ${p.title} to cart` : `${p.title} is sold out`}
      {...buttonBase}
      {...addToCart}
      css={[addToCartCss, focusRing, minTargetSize]}
      background={!p.inStock ? "#d1d5db" : "#2563eb"}
      color={!p.inStock ? "#6b7280" : "#fff"}
      cursor={!p.inStock ? "not-allowed" : "pointer"}
    >
      {p.inStock ? "Add to cart" : "Sold out"}
    </styled.button>
  </styled.li>
);

export default (i: number) => {
  const p: Product = {
    i,
    title: "Product " + i,
    price: (i % 50) + 9.99,
    discount: i % 4 === 0 ? (i % 3 === 0 ? 40 : 20) : 0,
    rating: (i % 5) + 1,
    inStock: i % 7 !== 0,
    wishlisted: i % 6 === 0,
  };
  return <Tile p={p} />;
};

// @ts-nocheck

// The base button every tap target is built from — exactly the props the wishlist and
// add-to-cart bundles both carry in the single-file product-grid, so the computed CSS
// is unchanged and the two cases stay comparable.
export const buttonBase = {
  border: "none",
  cursor: "pointer",
} as const;

// @ts-nocheck

// The two tap targets. Their shared border/cursor now come from the imported base
// button, which the page spreads in ahead of these.

export const wishlist = {
  position: "absolute",
  top: "6px",
  right: "6px",
  borderRadius: "9999px",
  background: "rgba(255, 255, 255, 0.8)",
  fontSize: "18px",
  lineHeight: "1",
  padding: "4px",
  color: "#9ca3af",
  transition: "color 0.15s ease",
} as const;

export const wishlistCss = {
  "@media (hover: hover)": {
    _hover: {
      color: "#ef4444",
    },
  },
  "@media (prefers-reduced-motion: reduce)": {
    transition: "none",
  },
} as const;

export const addToCart = {
  marginTop: "auto",
  position: "relative",
  borderRadius: "6px",
  padding: "8px 12px",
  fontSize: "14px",
  fontWeight: "600",
  color: "#fff",
  background: "#2563eb",
  transition: "background-color 0.15s ease",
} as const;

export const addToCartCss = {
  "@media (hover: hover)": {
    "&:hover:not(:disabled)": {
      background: "#1d4ed8",
    },
  },
  "@media (prefers-reduced-motion: reduce)": {
    transition: "none",
  },
  "@media (min-width: 992px)": {
    padding: "9px 12px",
  },
} as const;

// @ts-nocheck

// Structure style bundles. Declarations only — no JSX use site lives in this module.

export const grid = {
  display: "grid",
  gridTemplateColumns: "repeat(2, minmax(0, 1fr))",
  gap: "8px",
  margin: "0",
  padding: "0",
  listStyle: "none",
} as const;

export const gridCss = {
  "@media (min-width: 640px)": {
    gridTemplateColumns: "repeat(3, minmax(0, 1fr))",
  },
  "@media (min-width: 992px)": {
    gridTemplateColumns: "repeat(4, minmax(0, 1fr))",
    gap: "16px",
  },
} as const;

export const card = {
  display: "flex",
  flexDirection: "column",
  // Each tile is its own query container, so its children adapt to the column
  // width they land in — not the viewport.
  containerType: "inline-size",
  containerName: "tile",
  border: "1px solid #e5e7eb",
  borderRadius: "8px",
  padding: "12px",
  background: "#fff",
  transition: "box-shadow 0.15s ease",
} as const;

export const cardCss = {
  "@media (hover: hover)": {
    _hover: {
      boxShadow: "0 4px 12px rgba(0, 0, 0, 0.08)",
    },
  },
  "@media (prefers-reduced-motion: reduce)": {
    transition: "none",
  },
} as const;

export const imageWrap = {
  position: "relative",
  aspectRatio: "1",
  background: "#f3f4f6",
  borderRadius: "6px",
  overflow: "hidden",
} as const;

export const imagePlaceholder = {
  position: "absolute",
  inset: "0",
  background: "linear-gradient(135deg, #f3f4f6 0%, #e5e7eb 100%)",
} as const;

// @ts-nocheck

// Copy, rating and price bundles. Declarations only — no JSX use site lives here.

export const badge = {
  position: "absolute",
  top: "6px",
  left: "6px",
  borderRadius: "4px",
  padding: "2px 6px",
  fontSize: "12px",
  fontWeight: "700",
  color: "#fff",
  background: "#f59e0b",
} as const;

export const title = {
  margin: "8px 0 4px",
  fontSize: "14px",
  fontWeight: "500",
  whiteSpace: "nowrap",
  overflow: "hidden",
  textOverflow: "ellipsis",
} as const;

export const titleCss = {
  "@media (min-width: 992px)": {
    fontSize: "15px",
  },
  // Wider columns get a slightly larger title.
  "@container tile (min-width: 240px)": {
    fontSize: "16px",
  },
} as const;

export const rating = {
  height: "8px",
  borderRadius: "4px",
  background: "#e5e7eb",
  overflow: "hidden",
} as const;

export const ratingFill = {
  height: "100%",
  background: "#fbbf24",
} as const;

export const priceRow = {
  display: "flex",
