// styled-components — btn-variant. Identical CSS to every other lane; the
// difference is the runtime: styled-components resolves these prop-driven rules
// and injects CSS at render. Default-exports a single-instance render(i) (§6);
// the harness loops it. btn-variant varies active/fullWidth/variant by index.
import React from 'react';
import { styled, css } from 'styled-components';

interface P {
  $active?: boolean;
  $fullWidth?: boolean;
  $variant?: 'primary' | 'secondary' | 'ghost';
  children?: React.ReactNode;
}

const Button = styled.button<P>`
  display:inline-flex;align-items:center;justify-content:center;border-radius:6px;padding:8px 16px;font-size:14px;line-height:20px;font-weight:500;background-color:#2563eb;color:#ffffff;
  ${(p) => !p.$active && 'background-color:#d1d5db;color:#6b7280;'}
  ${(p) => p.$variant === 'secondary' && 'background-color:#f3f4f6;color:#111827;'}
  ${(p) => p.$variant === 'ghost' && 'background-color:transparent;color:#2563eb;'}
  ${(p) => p.$fullWidth && 'width:100%;'}
`;

export default (i: number) => {
  const variant = (['primary', 'secondary', 'ghost'] as const)[i % 3];
  return (
    <Button
      $active={i % 4 !== 0}
      $fullWidth={i % 3 === 0}
      $variant={variant}
    >
      {i}
    </Button>
  );
};

// bench-strategy: variant-ladder-jsx-components
// styled-components — button-variants-nested. Three modules, each exporting a JSX COMPONENT:
// Button, GhostButton extending it, GhostPrimaryButton extending that. The module
// API is the component, so every lane wraps — the page only renders the leaf.
// Paired with button-variants (same ladder as style values merged at one element).
import React from "react";
import { GhostPrimaryButton } from "./ghost-primary-button";

export default (i: number) => <GhostPrimaryButton>{i}</GhostPrimaryButton>;

import { styled } from "styled-components";

export const Button = styled.button`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-width: 1px;
  border-style: solid;
  border-color: transparent;
  border-radius: 6px;
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  cursor: pointer;
  background: #2563eb;
  color: #fff;
`;

import { styled } from "styled-components";
import { Button } from "./button";

export const GhostButton = styled(Button)`
  background: transparent;
  border-color: #d1d5db;
  color: #374151;
`;

import { styled } from "styled-components";
import { GhostButton } from "./ghost-button";

export const GhostPrimaryButton = styled(GhostButton)`
  border-color: #2563eb;
  color: #2563eb;
`;

// bench-strategy: variant-ladder-style-values
// styled-components — button-variants. Three modules, each exporting a STYLE VALUE (not a
// component): base button, ghost override, ghost-primary override. index.tsx
// merges all three onto ONE element, which is how this library composes styles.
// Paired with button-variants-nested, which ships the same ladder as a JSX
// component API — the pair prices the API shape, not the file layout (both split).
import React from "react";
import { styled } from "styled-components";
import { button } from "./button";
import { ghostButton } from "./ghost-button";
import { ghostPrimaryButton } from "./ghost-primary-button";

// One styled component, three interpolated fragments — the runtime serialises the
// ladder once per class, not once per level per render.
const GhostPrimaryButton = styled.button`
  ${button};
  ${ghostButton};
  ${ghostPrimaryButton};
`;

export default (i: number) => <GhostPrimaryButton>{i}</GhostPrimaryButton>;

import { css } from "styled-components";

export const button = css`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-width: 1px;
  border-style: solid;
  border-color: transparent;
  border-radius: 6px;
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  cursor: pointer;
  background: #2563eb;
  color: #fff;
`;

import { css } from "styled-components";

export const ghostButton = css`
  background: transparent;
  border-color: #d1d5db;
  color: #374151;
`;

import { css } from "styled-components";

export const ghostPrimaryButton = css`
  border-color: #2563eb;
  color: #2563eb;
`;

// bench-strategy: compose-depth
// styled-components — compose-1, the depth-sweep control. ONE styled component
// carrying only the compose-3 base-level styles: no styled(styled) chain, so this is
// the floor the compose-3/compose-6 wrapper costs are measured against.
// Default-exports a single-instance render(i) (§6); the harness loops it.
import React from 'react';
import { styled } from 'styled-components';

const ComposedButton = styled.button`display:inline-flex;align-items:center;border-radius:6px;padding:8px 16px;background:#2563eb;color:#fff;`;

export default (i: number) => {
  return <ComposedButton>{i}</ComposedButton>;
};

// styled-components — compose-3. Identical CSS to every other lane; the
// difference is the runtime: styled-components flattens the 3-deep styled(styled)
// chain and injects CSS at render. Default-exports a single-instance render(i)
// (§6); the harness loops it.
import React from 'react';
import { styled } from 'styled-components';

interface P { children?: React.ReactNode; }

const L0 = styled.button`display:inline-flex;align-items:center;border-radius:6px;padding:8px 16px;background:#2563eb;color:#fff;`;
const L1 = styled(L0)`border-left:1px solid hsl(53 70% 50%);padding-left:2px;`;
const L2 = styled(L1)`border-left:2px solid hsl(106 70% 50%);padding-left:4px;`;
export default (i: number) => {
  return <L2>{i}</L2>;
};

// bench-strategy: compose-depth
// styled-components — compose-6, the depth-sweep upper bracket. The compose-3 chain
// extended three more levels (L3–L5), each adding one small border-left/padding-left
// declaration, so the runtime flattens a 6-deep styled(styled) chain per render.
// Default-exports a single-instance render(i) (§6); the harness loops it.
import React from 'react';
import { styled } from 'styled-components';

const L0 = styled.button`display:inline-flex;align-items:center;border-radius:6px;padding:8px 16px;background:#2563eb;color:#fff;`;
const L1 = styled(L0)`border-left:1px solid hsl(53 70% 50%);padding-left:2px;`;
const L2 = styled(L1)`border-left:2px solid hsl(106 70% 50%);padding-left:4px;`;
const L3 = styled(L2)`border-left:3px solid hsl(159 70% 50%);padding-left:6px;`;
const L4 = styled(L3)`border-left:4px solid hsl(212 70% 50%);padding-left:8px;`;
const L5 = styled(L4)`border-left:5px solid hsl(265 70% 50%);padding-left:10px;`;
export default (i: number) => {
  return <L5>{i}</L5>;
};

// bench-strategy: inline-style
// styled-components — the documented best practice for a fully dynamic value: keep the
// template static (ONE class for all instances) and pass the per-instance transform as
// an inline style via .attrs, as the styled-components FAQ recommends for styles that
// change many times ("over 50 times per second"/high-cardinality values). Default-exports
// render(i) (§6); the harness loops it.
import React from 'react';
import { styled } from 'styled-components';

interface P {
  $translateX: number;
  children?: React.ReactNode;
}

const TranslatedDot = styled.div.attrs<P>(({ $translateX }) => ({
  style: { transform: `translateX(${$translateX}px)` },
}))`
  display:inline-block;width:8px;height:8px;
`;

export default (i: number) => {
  return <TranslatedDot $translateX={i}>{i}</TranslatedDot>;
};

// styled-components — dyn-translate. Identical CSS to every other lane; the
// difference is the runtime: styled-components resolves the per-instance
// transform and injects a unique rule at render. Default-exports a
// single-instance render(i) (§6); the harness loops it. HIGH cardinality: every i
// yields a distinct translateX value, so each instance produces a new class.
import React from 'react';
import { styled } from 'styled-components';

interface P {
  $translateX: number;
  children?: React.ReactNode;
}

const TranslatedDot = styled.div<P>`
  display:inline-block;width:8px;height:8px;
  transform: translateX(${({ $translateX }) => $translateX}px);
`;

export default (i: number) => {
  return <TranslatedDot $translateX={i}>{i}</TranslatedDot>;
};

// bench-strategy: same-as-tabs-multifile
import { Tab, Tabs, FullWidthTabs } from "./parts";

// --- workload ----------------------------------------------------------------
const LABELS = ["Overview", "Specs", "Reviews", "Q&A", "Similar", "Deals", "Support", "More"];
interface Group { id: number; count: number; activeIdx: number; fullWidth: boolean; disabledIdx: number; }

const TabGroup = ({ group }: { group: Group }) => (
  <Tabs>
    {Array.from({ length: group.count }, (_, t) => (
      <Tab
        key={t}
        isActive={t === group.activeIdx}
        disabled={t === group.disabledIdx && t !== group.activeIdx}
      >
        {LABELS[t % LABELS.length]}
      </Tab>
    ))}
  </Tabs>
);

const FullWidthTabGroup = ({ group }: { group: Group }) => (
  <FullWidthTabs>
    {Array.from({ length: group.count }, (_, t) => (
      <Tab
        key={t}
        isActive={t === group.activeIdx}
        disabled={t === group.disabledIdx && t !== group.activeIdx}
      >
        {LABELS[t % LABELS.length]}
      </Tab>
    ))}
  </FullWidthTabs>
);

export default (i: number) => {
  const count = 3 + (i % 6);
  const group: Group = {
    id: i,
    count,
    activeIdx: i % count,
    fullWidth: i % 3 === 0,
    disabledIdx: i % 4 === 0 ? count - 1 : -1,
  };
  return group.fullWidth ? <FullWidthTabGroup group={group} /> : <TabGroup group={group} />;
};

// styled-components — the real-project Tabs. Identical CSS to every other lane;
// the difference is the runtime: styled-components re-runs all of this through
// its runtime on every render. Default-exports a single-instance render(i) (§6);
// the harness loops it. tabs builds ONE TabGroup from i (same formula as the old
// 150-group DATA array).
import React, { type ButtonHTMLAttributes, type FunctionComponent, type KeyboardEvent, type ReactNode } from "react";
import { css, styled } from "styled-components";

// The SAME real-project Tabs expressed with styled-components: responsive copy
// typography, normal/active/hover/focus-visible/disabled states, an animated
// active underline via CSS anchor positioning (per-tab ::after fallback under
// @supports), a ::before WCAG 40px min-target, hidden-scrollbar overflow, and a
// composed FullWidthTabs wrapper. styled-components re-runs all of this through
// its runtime on every render. (The Emotion lane is derived from this file.)
const desktop = "@media (min-width: 992px)";

const copyTypography = css`
  font-size: 16px;
  line-height: 24px;
  letter-spacing: 0.01em;
  font-weight: 400;
  ${desktop} {
    font-size: 14px;
    line-height: 20px;
  }
`;

const normalTabStyle = css`
  position: relative;
  display: inline-flex;
  align-items: center;
  ${copyTypography};
  cursor: pointer;
  color: rgba(0, 0, 0, 0.6);
  background-color: transparent;
  height: 40px;

  &::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    border-bottom: 3px solid transparent;
    transition: opacity 150ms linear;
  }

  &::before {
    position: absolute;
    content: "";
    width: 100%;
    min-width: 40px;
    top: 0;
    bottom: 0;
    height: 100%;
  }
`;

const activeTabStyle = css`
  color: #000;

  @supports (anchor-name: --test) {
    anchor-name: --active-tab;
  }

  &::after {
    border-bottom-color: #eeb524;

    @supports (anchor-name: --test) {
      border-bottom-color: #ddd;
      opacity: 0;
    }
  }
`;

const hoverTabStyle = css`
  color: #000;

  &::after {
    border-bottom-color: #ddd;
  }
`;

const focusVisibleTabStyle = css`
  outline: none;

  &&::after {
    border-bottom: 3px solid #007bc7;
  }
`;

const disabledTabStyle = css`
  color: rgba(0, 0, 0, 0.26);
  cursor: default;
`;

interface ITabProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  isActive?: boolean;
  disabled?: boolean;
}

const TabListItem = styled.li`
  display: block;
  margin: 0;
  padding: 0;
  width: min-content;
  flex-shrink: 0;
  min-width: 40px;
`;

const TabInternal = ({ isActive, disabled, ...props }: ITabProps) => (
  <TabListItem role="presentation">
    <button
      {...props}
      type="button"
      role="tab"
      disabled={disabled}
      aria-selected={isActive}
      tabIndex={isActive ? 0 : -1}
    />
  </TabListItem>
);

const Tab = styled(TabInternal)<ITabProps>`
  border-style: none;

  ${normalTabStyle};
  &:focus-visible {
    ${focusVisibleTabStyle};
  }
  ${({ isActive }) =>
    isActive
      ? css`
          ${activeTabStyle};
        `
      : css`
          &:hover:not(:disabled) {
            ${hoverTabStyle};
          }

          &:disabled {
            ${disabledTabStyle};
          }
        `}
`;

const TabList = styled.ul`
  position: relative;
  white-space: nowrap;
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  gap: 24px;
  box-shadow: inset 0 -1px 0 0 #ddd;
  margin: 0;
  padding: 0;
  list-style: none;

  scrollbar-width: none;
  &::-webkit-scrollbar {
    display: none;
  }

  @supports (anchor-name: --test) {
    &::before {
      content: "";
      position: absolute;
      bottom: 0;
      position-anchor: --active-tab;
      left: anchor(left);
      right: anchor(right);
      height: 3px;
      background-color: #eeb524;
      transition:
        left 150ms ease-out,
        right 150ms ease-out;
    }
  }
`;

interface ITabsProps {
  className?: string;
  children: ReactNode;
}

const Tabs: FunctionComponent<ITabsProps> = ({ children, className }) => (
  <TabList role="tablist" onKeyDown={handleKeyDown} className={className}>
    {children}
  </TabList>
);

const FullWidthTabs = styled(Tabs)`
  & > li {
    flex: 1;
    display: flex;
    justify-content: center;
  }
  & button {
    flex: 1;
  }
`;

// --- keyboard navigation (roving tabindex) ----------------------------------
const queryTab = (el: Element | null | undefined) =>
  el?.querySelector("button") ?? null;
const firstTab = (list: HTMLUListElement) => queryTab(list.firstElementChild)?.focus();
const lastTab = (list: HTMLUListElement) => queryTab(list.lastElementChild)?.focus();
const nextTab = (list: HTMLUListElement) => {
  const n = queryTab(document.activeElement?.parentElement?.nextElementSibling);
  n ? n.focus() : firstTab(list);
};
const prevTab = (list: HTMLUListElement) => {
  const p = queryTab(document.activeElement?.parentElement?.previousElementSibling);
  p ? p.focus() : lastTab(list);
};
function handleKeyDown(event: KeyboardEvent<HTMLUListElement>) {
  const node = event.currentTarget;
  switch (event.key) {
    case "ArrowRight": nextTab(node); break;
    case "ArrowLeft": prevTab(node); break;
    case "Home": event.preventDefault(); firstTab(node); break;
    case "End": event.preventDefault(); lastTab(node); break;
  }
}

export { Tab, Tabs, FullWidthTabs };

// bench-strategy: same-as-product-grid-multifile
// styled-components — multifile-shop. The SAME tile as product-grid (same DOM, same CSS,
// same product data), laid out the way a design system ships it: shared fragments
// in tokens.ts, a base button in button.tsx, and the primitives split by role over
// layout / controls / text. Nothing here folds — styled-components resolves the chain at render either way.
import React, { type FunctionComponent } from "react";
import { Card, ImageWrap, ImagePlaceholder } from "./layout";
import { Wishlist, AddToCart } from "./controls";
import { Badge, Title, Rating, RatingFill, PriceRow, OldPrice, NowPrice, SrOnly } from "./text";

interface Product {
  i: number;
  title: string;
  price: number;
  discount: number;
  rating: number;
  inStock: boolean;
  wishlisted: boolean;
}

const Tile: FunctionComponent<{ p: Product }> = ({ p }) => (
  <Card>
    <ImageWrap>
      <ImagePlaceholder aria-hidden="true" />
      {p.discount > 0 && (
        <Badge $high={p.discount >= 30}>
          <SrOnly>Reduced by </SrOnly>-{p.discount}%
        </Badge>
      )}
      <Wishlist
        $on={p.wishlisted}
        type="button"
        aria-pressed={p.wishlisted}
        aria-label={p.wishlisted ? "Remove from wishlist" : "Add to wishlist"}
      >
        <span aria-hidden="true">♥</span>
      </Wishlist>
    </ImageWrap>
    <Title>{p.title}</Title>
    <Rating role="img" aria-label={`Rated ${p.rating} out of 5`}>
      <RatingFill aria-hidden="true" $pct={(p.rating / 5) * 100} />
    </Rating>
    <PriceRow>
      {p.discount > 0 && (
        <OldPrice>
          <SrOnly>Was </SrOnly>${(p.price * (1 + p.discount / 100)).toFixed(2)}
        </OldPrice>
      )}
      <NowPrice>
        {p.discount > 0 && <SrOnly>Now </SrOnly>}${p.price.toFixed(2)}
      </NowPrice>
    </PriceRow>
    <AddToCart
      $disabled={!p.inStock}
      disabled={!p.inStock}
      aria-label={p.inStock ? `Add ${p.title} to cart` : `${p.title} is sold out`}
    >
      {p.inStock ? "Add to cart" : "Sold out"}
    </AddToCart>
  </Card>
);

export default (i: number) => {
  const item: Product = {
    i,
    title: "Product " + i,
    price: (i % 50) + 9.99,
    discount: i % 4 === 0 ? (i % 3 === 0 ? 40 : 20) : 0,
    rating: (i % 5) + 1,
    inStock: i % 7 !== 0,
    wishlisted: i % 6 === 0,
  };
  return <Tile p={item} />;
};

import { styled } from "styled-components";
import { focusRing, minTargetSize } from "./tokens";

