import { media } from "./tokens.stylex";

// Copy, rating and price bundles. Declarations only — no JSX use site lives here.
export const textStyles = stylex.create({
  badge: {
    position: "absolute",
    top: "6px",
    left: "6px",
    borderRadius: "4px",
    padding: "2px 6px",
    fontSize: "12px",
    fontWeight: 700,
    color: "#fff",
