// bench-strategy: same-as-tabs-multifile
import { Tab, Tabs, FullWidthTabs } from "./parts";

const LABELS = ["Overview", "Specs", "Reviews", "Q&A", "Similar", "Deals", "Support", "More"];
interface Group { id: number; count: number; activeIdx: number; fullWidth: boolean; disabledIdx: number; }

// The group arrives as an accessor: a dynamic JSX prop compiles to a getter, so
// `group={g()}` would rebuild the object on every read of it. `disabled` is computed by
// a call rather than written as `&&` inline, because the compiler wraps a logical
// expression in a prop position in a memo — a whole memo node per tab for a boolean.
const isDisabled = (g: Group, t: number) => t === g.disabledIdx && t !== g.activeIdx;

const TabGroup = (props: { group: () => Group }) => (
  <Tabs>
    {Array.from({ length: props.group().count }, (_, t) => (
      <Tab
        isActive={t === props.group().activeIdx}
        disabled={isDisabled(props.group(), t)}
      >
        {LABELS[t % LABELS.length]}
      </Tab>
    ))}
  </Tabs>
);

const FullWidthTabGroup = (props: { group: () => Group }) => (
  <FullWidthTabs>
    {Array.from({ length: props.group().count }, (_, t) => (
      <Tab
        isActive={t === props.group().activeIdx}
        disabled={isDisabled(props.group(), t)}
        fullWidth
      >
        {LABELS[t % LABELS.length]}
      </Tab>
    ))}
  </FullWidthTabs>
);

export default (i: () => number) => {
  // ONE tab group built from i with the same per-group formula as every other lane.
  // Cached on the index: the accessor is read many times per render and the formula is
  // the same every time, so rebuilding the object per read would be pure waste.
  let last = NaN;
  let cached!: Group;
  const g = (): Group => {
    const n = i();
    if (n !== last) {
      last = n;
      const count = 3 + (n % 6);
      cached = { id: n, count, activeIdx: n % count, fullWidth: n % 3 === 0, disabledIdx: n % 4 === 0 ? count - 1 : -1 };
    }
    return cached;
  };
  return <>{g().fullWidth ? <FullWidthTabGroup group={g} /> : <TabGroup group={g} />}</>;
};

// @ts-nocheck
import type { JSX } from "@solidjs/web";
import * as stylex from "@stylexjs/stylex";

// The same real-project Tabs in StyleX on Solid, split across modules the way a design
// system ships them: this file owns the styles and the components, index.tsx the workload. StyleX is atomic-per-element, so two
// styled-components features can't be expressed and are intentionally dropped:
//   • the CSS anchor-positioning animated underline (@supports anchor-name) — a
//     progressive enhancement the styled version itself guards behind @supports;
//     the StyleX lane renders the per-tab ::after underline fallback (the path
//     every shipping browser uses today).
//   • descendant selectors (FullWidthTabs' `& > li`, `& button`) — applied
//     directly to the li/button via a threaded `fullWidth` style instead.
// Everything else (normal/active/hover/focus-visible/disabled states, the ::after
// underline, the ::before 40px target, responsive copy typography, hidden-scrollbar
// overflow, roving-tabindex keyboard nav) is faithful.
const desktop = "@media (min-width: 992px)";

const styles = stylex.create({
  list: {
    position: "relative",
    whiteSpace: "nowrap",
    display: "flex",
    flexWrap: "nowrap",
    overflowX: "auto",
    gap: "24px",
    boxShadow: "inset 0 -1px 0 0 #ddd",
    margin: 0,
    padding: 0,
    listStyle: "none",
    scrollbarWidth: "none",
    "::-webkit-scrollbar": { display: "none" },
  },
  item: {
    display: "block",
    margin: 0,
    padding: 0,
    width: "min-content",
    flexShrink: 0,
    minWidth: "40px",
  },
  itemFull: { flex: 1, display: "flex", justifyContent: "center" },
  tab: {
    borderStyle: "none",
    position: "relative",
    display: "inline-flex",
    alignItems: "center",
    fontSize: { default: "16px", [desktop]: "14px" },
    lineHeight: { default: "24px", [desktop]: "20px" },
    letterSpacing: "0.01em",
    fontWeight: 400,
    backgroundColor: "transparent",
    height: "40px",
    outline: { default: null, ":focus-visible": "none" },
    "::after": {
      content: "''",
      position: "absolute",
      bottom: 0,
      left: 0,
      right: 0,
      borderBottomWidth: "3px",
      borderBottomStyle: "solid",
      transition: "opacity 150ms linear",
    },
    "::before": {
      content: "''",
      position: "absolute",
      width: "100%",
      minWidth: "40px",
      top: 0,
      bottom: 0,
      height: "100%",
    },
  },
  inactive: {
    color: { default: "rgba(0, 0, 0, 0.6)", ":hover:not(:disabled)": "#000", ":disabled": "rgba(0, 0, 0, 0.26)" },
    cursor: { default: "pointer", ":disabled": "default" },
    "::after": {
      borderBottomColor: { default: "transparent", ":hover:not(:disabled)": "#ddd", ":focus-visible": "#007bc7" },
    },
  },
  active: {
    color: "#000",
    "::after": { borderBottomColor: { default: "#eeb524", ":focus-visible": "#007bc7" } },
  },
  tabFull: { flex: 1 },
});

interface ITabProps {
  isActive?: boolean;
  disabled?: boolean;
  fullWidth?: boolean;
  children?: JSX.Element;
}

// aria-selected is written as an explicit string: React serializes a boolean attribute
// value, Solid would emit the attribute bare.
const Tab = (props: ITabProps) => (
  <li role="presentation" {...stylex.attrs(styles.item, props.fullWidth && styles.itemFull)}>
    <button
      type="button"
      role="tab"
      disabled={props.disabled}
      aria-selected={props.isActive ? "true" : "false"}
      tabindex={props.isActive ? 0 : -1}
      {...stylex.attrs(styles.tab, props.isActive ? styles.active : styles.inactive, props.fullWidth && styles.tabFull)}
    >
      {props.children}
    </button>
  </li>
);

interface ITabsProps {
  children: JSX.Element;
}

const Tabs = (props: ITabsProps) => (
  <ul role="tablist" onKeyDown={handleKeyDown} {...stylex.attrs(styles.list)}>
    {props.children}
  </ul>
);

const FullWidthTabs = (props: ITabsProps) => (
  <ul role="tablist" onKeyDown={handleKeyDown} {...stylex.attrs(styles.list)}>
    {props.children}
  </ul>
);

// roving-tabindex keyboard navigation (identical behaviour to the styled lane)
const queryTab = (el: Element | null | undefined) => el?.querySelector("button") ?? null;
const firstTab = (list: HTMLUListElement) => queryTab(list.firstElementChild)?.focus();
const lastTab = (list: HTMLUListElement) => queryTab(list.lastElementChild)?.focus();
const nextTab = (list: HTMLUListElement) => {
  const n = queryTab(document.activeElement?.parentElement?.nextElementSibling);
  n ? n.focus() : firstTab(list);
};
const prevTab = (list: HTMLUListElement) => {
  const p = queryTab(document.activeElement?.parentElement?.previousElementSibling);
  p ? p.focus() : lastTab(list);
};
function handleKeyDown(event: KeyboardEvent & { currentTarget: HTMLUListElement }) {
  const node = event.currentTarget;
  switch (event.key) {
    case "ArrowRight": nextTab(node); break;
    case "ArrowLeft": prevTab(node); break;
    case "Home": event.preventDefault(); firstTab(node); break;
    case "End": event.preventDefault(); lastTab(node); break;
  }
}

export { Tab, Tabs, FullWidthTabs };

