// vanilla lane — the hand-written ceiling for a variant button. Plain conditional class
// names over author-written CSS (./styles.css): no library, no runtime merge. Default-
// exports a single-instance render(i) (§6); the harness loops it. The per-item prop shape
// and class-assembly are verbatim from the original vanilla btn-variant lane.
import React, { type FunctionComponent } from "react";

interface P {
  $active?: boolean;
  $fullWidth?: boolean;
  $variant?: "primary" | "secondary" | "ghost";
  children?: React.ReactNode;
}

const Button: FunctionComponent<P> = ({ $active, $fullWidth, $variant, children }) => {
  let c = "btn";
  if (!$active) c += " btnInactive";
  if ($variant === "secondary") c += " btnSecondary";
  if ($variant === "ghost") c += " btnGhost";
  if ($fullWidth) c += " btnFull";
  return <button className={c}>{children}</button>;
};

export default (i: number) => {
  const variant = (["primary", "secondary", "ghost"] as const)[i % 3];
  return (
    <Button
      $active={i % 4 !== 0}
      $fullWidth={i % 3 === 0}
      $variant={variant}
    >
      {i}
    </Button>
  );
};

/* Author-written CSS for the variant button — the ceiling every lane compiles toward.
   Returned verbatim as the `css` half of renderCase() (§6.1); the vanilla SSR entry
   imports it ?raw. Maps the styled-components btn-variant declarations onto vanilla's
   semantic class names (btn / btnInactive / btnSecondary / btnGhost / btnFull). */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  padding: 8px 16px;
  font-size: 14px;
  line-height: 20px;
  font-weight: 500;
  background-color: #2563eb;
  color: #ffffff;
}
.btnInactive {
  background-color: #d1d5db;
  color: #6b7280;
}
.btnSecondary {
  background-color: #f3f4f6;
  color: #111827;
}
.btnGhost {
  background-color: transparent;
  color: #2563eb;
}
.btnFull {
  width: 100%;
}

