// vanilla-solid — button-variants-nested. Three modules, each exporting a JSX COMPONENT:
// Button, GhostButton extending it, GhostPrimaryButton extending that. The module API is
// the component, so every lane wraps — the page only renders the leaf.
import { GhostPrimaryButton } from "./ghost-primary-button";

// The wrapper chain with no library behind it: three components, one element, plain
// string concatenation per level. The floor the merges are measured against.
export default (i: () => number) => <GhostPrimaryButton>{i()}</GhostPrimaryButton>;

import type { JSX } from "@solidjs/web";

export const Button = (props: { class?: string; children?: JSX.Element }) => (
  <button class={props.class ? `btn ${props.class}` : "btn"}>{props.children}</button>
);

import type { JSX } from "@solidjs/web";
import { Button } from "./button";

export const GhostButton = (props: { class?: string; children?: JSX.Element }) => (
  <Button class={props.class ? `btn-ghost ${props.class}` : "btn-ghost"}>{props.children}</Button>
);

import type { JSX } from "@solidjs/web";
import { GhostButton } from "./ghost-button";

export const GhostPrimaryButton = (props: { children?: JSX.Element }) => (
  <GhostButton class="btn-ghost-primary">{props.children}</GhostButton>
);

/* Author-written CSS for the ghost-primary button ladder — the ceiling every lane
   compiles toward. Returned verbatim as the `css` half of renderCase() (§6.1); the
   vanilla SSR entry imports it ?raw. Three flat classes on one element, later rules
   winning, which is what the wrapper chains and the merges all resolve to. */
