// vanilla-solid lane — the hand-written speed-of-light ceiling. Plain class names over
// author-written CSS (./styles.css). No styling library, no runtime: this is what the
// yak-solid lane is measured against — so it renders the SAME DenseButton as the React
// lanes' shared template, structure-for-structure and pixel-for-pixel.
//
// realistic-button varies variant/disabled/icon by index (it is NOT a static case): the
// button alternates standard/primary, is disabled every 5th instance, and shows the icon
// on even instances — identical to the shared template.
const Icon = () => (
  <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true">
    <path d="M8 0l2 6h6l-5 4 2 6-5-4-5 4 2-6-5-4h6z" fill="currentColor" />
  </svg>
);

export default (i: () => number) => {
  const variant = () => (i() % 2 ? "primary" : "standard");
  const disabled = () => i() % 5 === 0;
  const hasIcon = () => i() % 2 === 0;
  return (
    <button type="button" class={`db-btn db-btn--${variant()}`} disabled={disabled()}>
      {hasIcon() && (
        <span class="db-btn__icon" aria-hidden="true">
          <Icon />
        </span>
      )}
      Buy {i()}
    </button>
  );
};

/* Author-written CSS for the DenseButton — the ceiling every lane compiles toward.
   Returned verbatim as the `css` half of renderCase() (§6.1); the vanilla SSR entry
   imports it ?raw. This is a flat-class translation of the SAME styled-components/emotion/
   goober template (base + responsive flip + :active + WCAG ::before tap target + the two
   variants + :disabled + the icon container), so the rendered pixels match those lanes. */
.db-btn {
  font-size: 16px;
  line-height: 24px;
  letter-spacing: 0.01em;
  font-weight: 400;
  display: flex;
  width: 100%;
  border: 1px solid rgba(0, 0, 0, 0.2);
  border-radius: 3px;
  align-items: center;
  justify-content: center;
  text-align: center;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
  padding: 7px 15px;
  position: relative;
}
@media (min-width: 992px) {
  .db-btn {
    font-size: 14px;
    line-height: 20px;
    padding: 1px 11px;
    display: inline-flex;
    width: auto;
  }
}
.db-btn:active:not(:disabled) {
  box-shadow: 0px 0px 2px rgba(0, 0, 0, 0.16), 0px 2px 4px rgba(0, 0, 0, 0.08);
}
.db-btn::before {
  content: "";
  position: absolute;
  inset: 50%;
  translate: -50% -50%;
  width: 100%;
  height: 100%;
  min-width: 24px;
  min-height: 24px;
}
.db-btn--primary,
.db-btn--primary:link,
.db-btn--primary:visited {
  color: #fff;
  background-color: #444;
}
.db-btn--primary:hover:not(:active, :disabled),
.db-btn--primary:focus-visible:not(:active, :disabled) {
  background-color: #000;
}
.db-btn--standard,
.db-btn--standard:link,
.db-btn--standard:visited {
  color: #000;
  background-color: #eee;
}
.db-btn--standard:hover:not(:active, :disabled),
.db-btn--standard:focus-visible:not(:active, :disabled) {
  background-color: #ddd;
}
.db-btn:disabled {
  color: rgba(0, 0, 0, 0.4);
  background-color: transparent;
  border-color: rgba(0, 0, 0, 0.1);
  cursor: default;
}
.db-btn__icon {
  display: flex;
  align-items: center;
  min-height: 24px;
  margin-right: 12px;
}
@media (min-width: 992px) {
  .db-btn__icon {
    min-height: 20px;
  }
}

