/* Author-written CSS for the Tabs group — the ceiling every lane compiles toward.
   Returned verbatim as the `css` half of renderCase() (§6.1); the vanilla SSR entry
   imports it ?raw. Mirrors what @yak/react/styled extract: responsive copy typography,
   the normal/active/hover/focus-visible/disabled state matrix, an animated active
   underline via CSS anchor positioning (per-tab ::after fallback under @supports), a
   ::before WCAG 40px min-target, hidden-scrollbar overflow and a full-width variant. */
.tab-item {
  display: block;
  margin: 0;
  padding: 0;
  width: min-content;
  flex-shrink: 0;
  min-width: 40px;
}
.tab {
  border-style: none;
  position: relative;
  display: inline-flex;
  align-items: center;
  font-size: 16px;
  line-height: 24px;
  letter-spacing: 0.01em;
  font-weight: 400;
  cursor: pointer;
  color: rgba(0, 0, 0, 0.6);
  background-color: transparent;
  height: 40px;
}
@media (min-width: 992px) {
  .tab {
    font-size: 14px;
    line-height: 20px;
  }
}
.tab::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  border-bottom: 3px solid transparent;
  transition: opacity 150ms linear;
}
.tab::before {
  position: absolute;
  content: "";
  width: 100%;
  min-width: 40px;
  top: 0;
  bottom: 0;
  height: 100%;
}
.tab:focus-visible {
  outline: none;
}
.tab:focus-visible::after {
  border-bottom: 3px solid #007bc7;
}
.tab-active {
  color: #000;
}
@supports (anchor-name: --test) {
  .tab-active {
    anchor-name: --active-tab;
  }
}
.tab-active::after {
  border-bottom-color: #eeb524;
}
@supports (anchor-name: --test) {
  .tab-active::after {
    border-bottom-color: #ddd;
    opacity: 0;
  }
}
.tab:not(.tab-active):hover:not(:disabled) {
  color: #000;
}
.tab:not(.tab-active):hover:not(:disabled)::after {
  border-bottom-color: #ddd;
}
.tab:not(.tab-active):disabled,
.tab-disabled {
  color: rgba(0, 0, 0, 0.26);
  cursor: default;
}
.tablist {
  position: relative;
  white-space: nowrap;
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  gap: 24px;
  box-shadow: inset 0 -1px 0 0 #ddd;
  margin: 0;
  padding: 0;
  list-style: none;
  scrollbar-width: none;
}
.tablist::-webkit-scrollbar {
  display: none;
}
@supports (anchor-name: --test) {
  .tablist::before {
    content: "";
    position: absolute;
    bottom: 0;
    position-anchor: --active-tab;
    left: anchor(left);
    right: anchor(right);
    height: 3px;
    background-color: #eeb524;
    transition:
      left 150ms ease-out,
      right 150ms ease-out;
  }
}
.tablist-full > li {
  flex: 1;
  display: flex;
  justify-content: center;
}
.tablist-full button {
  flex: 1;
}

