import { styled, css } from "@yak/solid";
import type { JSX } from "@solidjs/web";

interface P {
  $active?: boolean;
  $fullWidth?: boolean;
  $variant?: 'primary' | 'secondary' | 'ghost';
  children?: JSX.Element;
}

const Button = styled.button<P>`
  display:inline-flex;align-items:center;justify-content:center;border-radius:6px;padding:8px 16px;font-size:14px;line-height:20px;font-weight:500;background-color:#2563eb;color:#ffffff;
  ${(p) => !p.$active && css`background-color:#d1d5db;color:#6b7280;`}
  ${(p) => p.$variant === 'secondary' && css`background-color:#f3f4f6;color:#111827;`}
  ${(p) => p.$variant === 'ghost' && css`background-color:transparent;color:#2563eb;`}
  ${(p) => p.$fullWidth && css`width:100%;`}
`;

export default (i: () => number) => {
  const variant = () => (['primary', 'secondary', 'ghost'] as const)[i() % 3];
  return (
    <Button
      $active={i() % 4 !== 0}
      $fullWidth={i() % 3 === 0}
      $variant={variant()}
    >
      {i()}
    </Button>
  );
};

// bench-strategy: variant-ladder-jsx-components
// @yak/solid — button-variants-nested. Three modules, each exporting a JSX COMPONENT:
// Button, GhostButton extending it, GhostPrimaryButton extending that. The module
// API is the component, so every lane wraps — the page only renders the leaf.
// Paired with button-variants (same ladder as style values merged at one element).
import { GhostPrimaryButton } from "./ghost-primary-button";

export default (i: () => number) => <GhostPrimaryButton>{i()}</GhostPrimaryButton>;

import { styled } from "@yak/solid";

/** The design system's base button. The module's API is the component itself. */
export const Button = styled.button`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-width: 1px;
  border-style: solid;
  border-color: transparent;
  border-radius: 6px;
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  cursor: pointer;
  background: #2563eb;
  color: #fff;
`;

import { styled } from "@yak/solid";
import { Button } from "./button";

/** styled(Component) across a module boundary — the fold never crosses it. */
export const GhostButton = styled(Button)`
  background: transparent;
  border-color: #d1d5db;
  color: #374151;
`;

import { styled } from "@yak/solid";
import { GhostButton } from "./ghost-button";

export const GhostPrimaryButton = styled(GhostButton)`
  border-color: #2563eb;
  color: #2563eb;
`;

// bench-strategy: variant-ladder-style-values
// @yak/solid — button-variants. Three modules, each exporting a STYLE VALUE (not a
// component): base button, ghost override, ghost-primary override. index.tsx
// merges all three onto ONE element, which is how this library composes styles.
// Paired with button-variants-nested, which ships the same ladder as a JSX
// component API — the pair prices the API shape, not the file layout (both split).
import { styled } from "@yak/solid";
import { button } from "./button";
import { ghostButton } from "./ghost-button";
import { ghostPrimaryButton } from "./ghost-primary-button";

// The styled component is declared AND used here, so the fold applies even though
// all three fragments crossed a module boundary: interpolated css values are
// resolved at build time, and only the element folds.
const GhostPrimaryButton = styled.button`
  ${button};
  ${ghostButton};
  ${ghostPrimaryButton};
`;

export default (i: () => number) => <GhostPrimaryButton>{i()}</GhostPrimaryButton>;

import { css } from "@yak/solid";

// The base button as a style VALUE. Exporting a css fragment rather than a
// component leaves the page free to merge it wherever it likes.
export const button = css`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-width: 1px;
  border-style: solid;
  border-color: transparent;
  border-radius: 6px;
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  cursor: pointer;
  background: #2563eb;
  color: #fff;
`;

import { css } from "@yak/solid";

/** Ghost override — wins over the base wherever they collide. */
export const ghostButton = css`
  background: transparent;
  border-color: #d1d5db;
  color: #374151;
`;

import { css } from "@yak/solid";

/** Brand override on top of ghost. */
export const ghostPrimaryButton = css`
  border-color: #2563eb;
  color: #2563eb;
`;

// bench-strategy: compose-depth
// @yak/solid — compose-1, the depth-sweep control: ONE styled component carrying only
// the compose-3 base-level styles, no styled(styled) chain to flatten.
import { styled } from "@yak/solid";

const ComposedButton = styled.button`display:inline-flex;align-items:center;border-radius:6px;padding:8px 16px;background:#2563eb;color:#fff;`;

export default (i: () => number) => <ComposedButton>{i()}</ComposedButton>;

// bench-strategy: compose-depth
// @yak/solid — compose-3, a 3-level styled(styled) chain the build flattens.
import { styled } from "@yak/solid";

const L0 = styled.button`display:inline-flex;align-items:center;border-radius:6px;padding:8px 16px;background:#2563eb;color:#fff;`;
const L1 = styled(L0)`border-left:1px solid hsl(53 70% 50%);padding-left:2px;`;
const L2 = styled(L1)`border-left:2px solid hsl(106 70% 50%);padding-left:4px;`;
export default (i: () => number) => <L2>{i()}</L2>;

// bench-strategy: compose-depth
// @yak/solid — compose-6, the depth-sweep upper bracket: the compose-3 chain extended
// three more levels (L3–L5), each adding one small border-left/padding-left
// declaration, so the build flattens a 6-deep styled(styled) chain.
import { styled } from "@yak/solid";

const L0 = styled.button`display:inline-flex;align-items:center;border-radius:6px;padding:8px 16px;background:#2563eb;color:#fff;`;
const L1 = styled(L0)`border-left:1px solid hsl(53 70% 50%);padding-left:2px;`;
const L2 = styled(L1)`border-left:2px solid hsl(106 70% 50%);padding-left:4px;`;
const L3 = styled(L2)`border-left:3px solid hsl(159 70% 50%);padding-left:6px;`;
const L4 = styled(L3)`border-left:4px solid hsl(212 70% 50%);padding-left:8px;`;
const L5 = styled(L4)`border-left:5px solid hsl(265 70% 50%);padding-left:10px;`;
export default (i: () => number) => <L5>{i()}</L5>;

// bench-strategy: inline-style
// @yak/solid — dyn-fair, for comparison only: the plain inline style over a static class that
// every other lane writes here, so the case compares like with like. This is NOT how a
// runtime value is written with yak. Its own path is a function interpolation the compiler
// turns into a CSS variable, and that is what dyn-translate measures; the gap between the
// two cases for this lane is what the CSS-variable path costs over the inline style.
// Default-exports render(i) (§6); the harness loops it.
import { styled } from "@yak/solid";
import type { JSX } from "@solidjs/web";

interface P {
  translateX: number;
  children?: JSX.Element;
}

const Dot = styled.div`
  display:inline-block;width:8px;height:8px;
`;

const TranslatedDot = (props: P) => (
  <Dot style={{ transform: `translateX(${props.translateX}px)` }}>{props.children}</Dot>
);

export default (i: () => number) => {
  return <TranslatedDot translateX={i()}>{i()}</TranslatedDot>;
};

import { styled } from "@yak/solid";
import type { JSX } from "@solidjs/web";

interface P {
  $translateX: number;
  children?: JSX.Element;
}

const TranslatedDot = styled.div<P>`
  display:inline-block;width:8px;height:8px;
  transform: translateX(${({ $translateX }) => $translateX}px);
`;

export default (i: () => number) => {
  return <TranslatedDot $translateX={i()}>{i()}</TranslatedDot>;
};

// bench-strategy: same-as-tabs-multifile
import { Tab, Tabs, FullWidthTabs } from "./parts";

// --- workload ----------------------------------------------------------------
const LABELS = ["Overview", "Specs", "Reviews", "Q&A", "Similar", "Deals", "Support", "More"];
interface Group { id: number; count: number; activeIdx: number; fullWidth: boolean; disabledIdx: number; }

// The group arrives as an accessor: a dynamic JSX prop compiles to a getter, so
// `group={group()}` would rebuild the object on every read of it. `disabled` is computed
// by a call rather than written as `&&` inline, because the compiler wraps a logical
// expression in a prop position in a memo — a whole memo node per tab for a boolean.
const isDisabled = (g: Group, t: number) => t === g.disabledIdx && t !== g.activeIdx;

const TabGroup = (props: { group: () => Group }) => (
  <Tabs>
    {Array.from({ length: props.group().count }, (_, t) => (
      <Tab
        isActive={t === props.group().activeIdx}
        disabled={isDisabled(props.group(), t)}
      >
        {LABELS[t % LABELS.length]}
      </Tab>
    ))}
  </Tabs>
);

const FullWidthTabGroup = (props: { group: () => Group }) => (
  <FullWidthTabs>
    {Array.from({ length: props.group().count }, (_, t) => (
      <Tab
        isActive={t === props.group().activeIdx}
        disabled={isDisabled(props.group(), t)}
      >
        {LABELS[t % LABELS.length]}
      </Tab>
    ))}
  </FullWidthTabs>
);

export default (g: () => number) => {
  // Cached on the index: the accessor is read many times per render and the formula is
  // the same every time, so rebuilding the object per read would be pure waste.
  let last = NaN;
  let cached!: Group;
  const group = (): Group => {
    const n = g();
    if (n !== last) {
      last = n;
      const count = 3 + (n % 6);
      cached = {
        id: n,
        count,
        activeIdx: n % count,
        fullWidth: n % 3 === 0,
        disabledIdx: n % 4 === 0 ? count - 1 : -1,
      };
    }
    return cached;
  };
  return <>{group().fullWidth ? <FullWidthTabGroup group={group} /> : <TabGroup group={group} />}</>;
};

import { omit } from "solid-js";
import type { JSX } from "@solidjs/web";
import { css, styled } from "@yak/solid";

// Port of a real-project Tabs component (galaxus design system). Exercises the
// hardest CSS this suite has: responsive copy typography, normal/active/hover/
// focus-visible/disabled states, an animated active underline via CSS anchor
// positioning (with a per-tab ::after fallback under @supports), a ::before WCAG
// 40px min-target-size, hidden-scrollbar horizontal overflow, and a composed
// FullWidthTabs wrapper. yak compiles ALL of it to build-time CSS; at
// runtime it only flips the active class. The Tailwind lanes must ship a ~40-
// token utility list per tab and conflict-resolve it on every render.
const desktop = "@media (min-width: 992px)";

const copyTypography = css`
  font-size: 16px;
  line-height: 24px;
  letter-spacing: 0.01em;
  font-weight: 400;
  ${desktop} {
    font-size: 14px;
    line-height: 20px;
  }
`;

const normalTabStyle = css`
  position: relative;
  display: inline-flex;
  align-items: center;
  ${copyTypography};
  cursor: pointer;
  color: rgba(0, 0, 0, 0.6);
  background-color: transparent;
  height: 40px;

  &::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    border-bottom: 3px solid transparent;
    transition: opacity 150ms linear;
  }

  &::before {
    position: absolute;
    content: "";
    width: 100%;
    min-width: 40px;
    top: 0;
    bottom: 0;
    height: 100%;
  }
`;

const activeTabStyle = css`
  color: #000;

  @supports (anchor-name: --test) {
    anchor-name: --active-tab;
  }

  &::after {
    border-bottom-color: #eeb524;

    @supports (anchor-name: --test) {
      border-bottom-color: #ddd;
      opacity: 0;
    }
  }
`;

const hoverTabStyle = css`
  color: #000;

  &::after {
    border-bottom-color: #ddd;
  }
`;

const focusVisibleTabStyle = css`
  outline: none;

  &&::after {
    border-bottom: 3px solid #007bc7;
  }
`;

const disabledTabStyle = css`
  color: rgba(0, 0, 0, 0.26);
  cursor: default;
`;

interface ITabProps extends JSX.ButtonHTMLAttributes<HTMLButtonElement> {
  isActive?: boolean;
  disabled?: boolean;
}

const TabListItem = styled.li`
  display: block;
  margin: 0;
  padding: 0;
  width: min-content;
  flex-shrink: 0;
  min-width: 40px;
`;

// Solid components run once and read props lazily, so the props object is passed
// along instead of destructured; `omit` keeps `isActive` off the DOM element.
const TabInternal = (props: ITabProps) => (
  <TabListItem role="presentation">
    <button
      {...omit(props, "isActive")}
      type="button"
      role="tab"
      disabled={props.disabled}
      aria-selected={props.isActive ? "true" : "false"}
      tabindex={props.isActive ? 0 : -1}
    />
  </TabListItem>
);

const Tab = styled(TabInternal)<ITabProps>`
  border-style: none;

  ${normalTabStyle};
  &:focus-visible {
    ${focusVisibleTabStyle};
  }
  ${({ isActive }) =>
    isActive
      ? css`
          ${activeTabStyle};
        `
      : css`
          &:hover:not(:disabled) {
            ${hoverTabStyle};
          }

          &:disabled {
            ${disabledTabStyle};
          }
        `}
`;

const TabList = styled.ul`
  position: relative;
  white-space: nowrap;
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  gap: 24px;
  box-shadow: inset 0 -1px 0 0 #ddd;
  margin: 0;
  padding: 0;
  list-style: none;

  scrollbar-width: none;
  &::-webkit-scrollbar {
    display: none;
  }

  @supports (anchor-name: --test) {
    &::before {
      content: "";
      position: absolute;
      bottom: 0;
      position-anchor: --active-tab;
      left: anchor(left);
      right: anchor(right);
      height: 3px;
      background-color: #eeb524;
      transition:
        left 150ms ease-out,
        right 150ms ease-out;
    }
  }
`;

interface ITabsProps {
  class?: string;
  children: JSX.Element;
}

const Tabs = (props: ITabsProps) => (
  <TabList role="tablist" onKeyDown={handleKeyDown} class={props.class}>
    {props.children}
  </TabList>
);

// Equal-width children. Uses element/descendant selectors (not styled-component
// references) so every lane is byte-equivalent and yak needs no component-
// selector support.
const FullWidthTabs = styled(Tabs)`
  & > li {
    flex: 1;
    display: flex;
    justify-content: center;
  }
  & button {
    flex: 1;
  }
`;

// --- keyboard navigation (roving tabindex) ----------------------------------
const queryTab = (el: Element | null | undefined) =>
  el?.querySelector("button") ?? null;
const firstTab = (list: HTMLUListElement) => queryTab(list.firstElementChild)?.focus();
const lastTab = (list: HTMLUListElement) => queryTab(list.lastElementChild)?.focus();
const nextTab = (list: HTMLUListElement) => {
  const n = queryTab(document.activeElement?.parentElement?.nextElementSibling);
  n ? n.focus() : firstTab(list);
};
const prevTab = (list: HTMLUListElement) => {
  const p = queryTab(document.activeElement?.parentElement?.previousElementSibling);
  p ? p.focus() : lastTab(list);
};
function handleKeyDown(event: KeyboardEvent & { currentTarget: HTMLUListElement }) {
  const node = event.currentTarget;
  switch (event.key) {
    case "ArrowRight": nextTab(node); break;
    case "ArrowLeft": prevTab(node); break;
    case "Home": event.preventDefault(); firstTab(node); break;
    case "End": event.preventDefault(); lastTab(node); break;
  }
}

export { Tab, Tabs, FullWidthTabs };

import { Card, Grid, ImagePlaceholder, ImageWrap } from "./layout";
import { AddToCart, Wishlist } from "./controls";
import { Badge, NowPrice, OldPrice, PriceRow, Rating, RatingFill, SrOnly, Title } from "./text";

// The SAME 400-tile shop page as product-grid — same DOM, same CSS, same product
// data — but laid out the way a design system ships it: shared fragments in
// tokens.ts, a base button in button.tsx, and the primitives split by role over
// layout/controls/text. Every JSX use site sits here, and the fold only rewrites
// usages declared in the SAME module, so nothing below folds: each <Card>, <Badge>,
// <Title> stays a runtime Yak wrapper, and the two controls extend an imported base
// through a dynamic styled(Component) the fold never crosses. Runtime libraries
// render this exactly as they render product-grid.

interface Product {
  i: number;
  title: string;
  price: number;
  discount: number;
  rating: number;
  inStock: boolean;
  wishlisted: boolean;
}

const Tile = (props: { p: () => Product }) => (
  <Card>
    <ImageWrap>
      <ImagePlaceholder aria-hidden="true" />
      {props.p().discount > 0 && (
        <Badge $high={props.p().discount >= 30}>
          <SrOnly>Reduced by </SrOnly>-{props.p().discount}%
        </Badge>
      )}
      <Wishlist
        $on={props.p().wishlisted}
        type="button"
        aria-pressed={props.p().wishlisted ? "true" : "false"}
        aria-label={props.p().wishlisted ? "Remove from wishlist" : "Add to wishlist"}
      >
        <span aria-hidden="true">♥</span>
      </Wishlist>
    </ImageWrap>
    <Title>{props.p().title}</Title>
    <Rating role="img" aria-label={`Rated ${props.p().rating} out of 5`}>
      <RatingFill aria-hidden="true" $pct={(props.p().rating / 5) * 100} />
    </Rating>
    <PriceRow>
      {props.p().discount > 0 && (
        <OldPrice>
          <SrOnly>Was </SrOnly>${(props.p().price * (1 + props.p().discount / 100)).toFixed(2)}
        </OldPrice>
      )}
      <NowPrice>
        {props.p().discount > 0 && <SrOnly>Now </SrOnly>}${props.p().price.toFixed(2)}
      </NowPrice>
    </PriceRow>
    <AddToCart
      $disabled={!props.p().inStock}
      disabled={!props.p().inStock}
      aria-label={props.p().inStock ? `Add ${props.p().title} to cart` : `${props.p().title} is sold out`}
    >
      {props.p().inStock ? "Add to cart" : "Sold out"}
    </AddToCart>
  </Card>
);

export default (i: () => number) => {
  // Cached on the index: `Tile` reads the product many times per render and a dynamic JSX
  // prop compiles to a getter, so the accessor is forwarded as a plain prop and the object
  // is built once per distinct index instead of once per read.
  let last = NaN;
  let cached!: Product;
  const p = (): Product => {
    const n = i();
    if (n !== last) {
      last = n;
      cached = {
        i: n,
        title: "Product " + n,
        price: (n % 50) + 9.99,
        discount: n % 4 === 0 ? (n % 3 === 0 ? 40 : 20) : 0,
        rating: (n % 5) + 1,
        inStock: n % 7 !== 0,
        wishlisted: n % 6 === 0,
      };
    }
    return cached;
  };
  return <Tile p={p} />;
};

import { styled } from "@yak/solid";
import { focusRing, minTargetSize } from "./tokens";

// The base button every tap target in the tile is built from — exactly the four
// declarations Wishlist and AddToCart both carry in the single-file product-grid,
// so the computed CSS is unchanged and the two cases stay comparable.
export const Button = styled.button`
  border: none;
  cursor: pointer;
  ${focusRing}
  ${minTargetSize}
`;

import { css, styled } from "@yak/solid";
import { Button } from "./button";
import { desktop } from "./tokens";

// The two tap targets, each EXTENDING the imported base button — the pattern a real
// design system ships. Both are dynamic styled(Component) across a module boundary,
// which the fold never rewrites.

export const Wishlist = styled(Button)<{ $on: boolean }>`
  position: absolute;
  top: 6px;
  right: 6px;
  border-radius: 9999px;
  background: rgba(255, 255, 255, 0.8);
  font-size: 18px;
  line-height: 1;
  padding: 4px;
  color: #9ca3af;
  transition: color 0.15s ease;
  @media (hover: hover) {
    &:hover {
      color: #ef4444;
    }
  }
  @media (prefers-reduced-motion: reduce) {
    transition: none;
  }
  ${({ $on }) => $on && css`color: #ef4444;`}
`;

export const AddToCart = styled(Button)<{ $disabled: boolean }>`
  margin-top: auto;
  position: relative;
  border-radius: 6px;
  padding: 8px 12px;
  font-size: 14px;
  font-weight: 600;
  color: #fff;
  background: #2563eb;
  transition: background-color 0.15s ease;
  @media (hover: hover) {
    &:hover:not(:disabled) {
      background: #1d4ed8;
    }
