const LABELS = ["Overview", "Specs", "Reviews", "Q&A", "Similar", "Deals", "Support", "More"];
interface Group { id: number; count: number; activeIdx: number; fullWidth: boolean; disabledIdx: number; }
interface ITabProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  isActive?: boolean;
  disabled?: boolean;
  fullWidth?: boolean;
}

const Tab: FunctionComponent<ITabProps> = ({ isActive, disabled, fullWidth, ...props }) => (
  <li role="presentation" classStyle={[styles.item, fullWidth && styles.itemFull]}>
    <button
      {...props}
      type="button"
      role="tab"
      disabled={disabled}
      aria-selected={isActive}
      tabIndex={isActive ? 0 : -1}
      classStyle={[styles.tab, isActive ? styles.active : styles.inactive, fullWidth && styles.tabFull]}
    />
  </li>
);

interface ITabsProps {
  children: ReactNode;
}

const Tabs: FunctionComponent<ITabsProps> = ({ children }) => (
  <ul role="tablist" onKeyDown={handleKeyDown} classStyle={styles.list}>
    {children}
  </ul>
);

const FullWidthTabs: FunctionComponent<ITabsProps> = ({ children }) => (
  <ul role="tablist" onKeyDown={handleKeyDown} classStyle={styles.list}>
    {children}
  </ul>
);

// roving-tabindex keyboard navigation (identical behaviour to the styled lane)
const queryTab = (el: Element | null | undefined) => el?.querySelector("button") ?? null;
const firstTab = (list: HTMLUListElement) => queryTab(list.firstElementChild)?.focus();
const lastTab = (list: HTMLUListElement) => queryTab(list.lastElementChild)?.focus();
const nextTab = (list: HTMLUListElement) => {
  const n = queryTab(document.activeElement?.parentElement?.nextElementSibling);
  n ? n.focus() : firstTab(list);
};
const prevTab = (list: HTMLUListElement) => {
  const p = queryTab(document.activeElement?.parentElement?.previousElementSibling);
  p ? p.focus() : lastTab(list);
};
function handleKeyDown(event: KeyboardEvent<HTMLUListElement>) {
  const node = event.currentTarget;
  switch (event.key) {
    case "ArrowRight": nextTab(node); break;
    case "ArrowLeft": prevTab(node); break;
    case "Home": event.preventDefault(); firstTab(node); break;
    case "End": event.preventDefault(); lastTab(node); break;
  }
}

export { Tab, Tabs, FullWidthTabs };

// bench-strategy: same-as-product-grid-multifile
// The product-grid workload is split into design-system modules. Plumeria resolves the
// cross-module compositions to literal class names just as it does in one file.
import React, { type FunctionComponent } from "react";
import "@plumeria/core";
import { buttonBase } from "./button";
import { shared } from "./tokens";
import { layoutStyles } from "./layout";
import { controlsStyles } from "./controls";
import { textStyles } from "./text";

interface Product {
  i: number;
  title: string;
  price: number;
  discount: number;
  rating: number;
  inStock: boolean;
  wishlisted: boolean;
}

const Tile: FunctionComponent<{ p: Product }> = ({ p }) => (
  <li classStyle={layoutStyles.card}>
    <div classStyle={layoutStyles.imageWrap}>
      <div aria-hidden="true" classStyle={layoutStyles.imagePlaceholder} />
      {p.discount > 0 && (
        <span classStyle={[textStyles.badge, p.discount >= 30 && textStyles.badgeHigh]}>
          <span classStyle={shared.srOnly}>Reduced by </span>-{p.discount}%
        </span>
      )}
      <button
        type="button"
        aria-pressed={p.wishlisted}
        aria-label={p.wishlisted ? "Remove from wishlist" : "Add to wishlist"}
        classStyle={[buttonBase.base, controlsStyles.wishlist, shared.focusRing, shared.minTarget, p.wishlisted && controlsStyles.wishlistOn]}
      >
        <span aria-hidden="true">♥</span>
      </button>
    </div>
    <h3 classStyle={textStyles.title}>{p.title}</h3>
    <div role="img" aria-label={`Rated ${p.rating} out of 5`} classStyle={textStyles.rating}>
      <div aria-hidden="true" classStyle={[textStyles.ratingFill, textStyles.fillW((p.rating / 5) * 100)]} />
    </div>
    <div classStyle={textStyles.priceRow}>
      {p.discount > 0 && (
        <span classStyle={textStyles.oldPrice}>
          <span classStyle={shared.srOnly}>Was </span>${(p.price * (1 + p.discount / 100)).toFixed(2)}
        </span>
      )}
      <span classStyle={textStyles.nowPrice}>
        {p.discount > 0 && <span classStyle={shared.srOnly}>Now </span>}${p.price.toFixed(2)}
      </span>
    </div>
    <button
      disabled={!p.inStock}
      aria-label={p.inStock ? `Add ${p.title} to cart` : `${p.title} is sold out`}
      classStyle={[buttonBase.base, controlsStyles.addToCart, shared.focusRing, shared.minTarget, !p.inStock && controlsStyles.addToCartDisabled]}
    >
      {p.inStock ? "Add to cart" : "Sold out"}
    </button>
  </li>
);

export default (i: number) => {
  const p: Product = {
    i,
    title: "Product " + i,
    price: (i % 50) + 9.99,
    discount: i % 4 === 0 ? (i % 3 === 0 ? 40 : 20) : 0,
    rating: (i % 5) + 1,
    inStock: i % 7 !== 0,
    wishlisted: i % 6 === 0,
  };
  return <Tile p={p} />;
};

