// The compiler resolves the build-time atomic styles and variant branches to literal
// class lists; variant, disabled and icon state still vary by instance.
import React from "react";
import * as css from "@plumeria/core";

const desktop = "@media (min-width: 992px)";

const styles = css.create({
  base: {
    position: "relative",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    width: "100%",
    padding: "7px 15px",
    fontSize: 16,
    fontWeight: 400,
    lineHeight: "24px",
    textAlign: "center",
    letterSpacing: "0.01em",
    whiteSpace: "nowrap",
    cursor: "pointer",
    userSelect: "none",
    borderColor: "rgba(0, 0, 0, 0.2)",
    borderStyle: "solid",
    borderWidth: 1,
    borderRadius: 3,
    ":active:not(:disabled)": {
      boxShadow: "0px 0px 2px rgba(0, 0, 0, 0.16), 0px 2px 4px rgba(0, 0, 0, 0.08)",
    },
    "::before": {
      position: "absolute",
      inset: "50%",
      width: "100%",
      minWidth: 24,
      height: "100%",
      minHeight: 24,
      content: '""',
      translate: "-50% -50%"
    },
    ":disabled": {
      color: "rgba(0, 0, 0, 0.4)",
      cursor: "default",
      backgroundColor: "transparent",
      borderColor: "rgba(0, 0, 0, 0.1)"
    },
    [desktop]: {
      display: "inline-flex",
      width: "auto",
      padding: "1px 11px",
      fontSize: 14,
      lineHeight: "20px"
    }
  },
  standard: {
    color: "#000",
    backgroundColor: "#eee",
    ":hover:not(:active, :disabled)": {
      backgroundColor: "#ddd"
    },
    ":focus-visible:not(:active, :disabled)": {
      backgroundColor: "#ddd"
    },
    ":hover:not(:active, :disabled):focus-visible": {
      backgroundColor: "#ddd"
    },
  },
  primary: {
    color: "#fff",
    backgroundColor: "#444",
    ":hover:not(:active, :disabled)": {
      backgroundColor: "#000"
    },
    ":focus-visible:not(:active, :disabled)": {
      backgroundColor: "#000"
    },
    ":hover:not(:active, :disabled):focus-visible": {
      backgroundColor: "#000"
    },
  },
  icon: {
    display: "flex",
    alignItems: "center",
    minHeight: 24,
    marginRight: 12,
    [desktop]: {
      minHeight: 20
    },
  },
});

const Icon = () => (
  <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true">
    <path d="M8 0l2 6h6l-5 4 2 6-5-4-5 4 2-6-5-4h6z" fill="currentColor" />
  </svg>
);

export default (i: number) => {
  const variant: "standard" | "primary" = i % 2 ? "primary" : "standard";
  const disabled = i % 5 === 0;
  const hasIcon = i % 2 === 0;
  return (
    <button
      type="button"
      disabled={disabled}
      classStyle={[styles.base, variant === "primary" ? styles.primary : styles.standard]}
    >
      {hasIcon && (
        <span aria-hidden="true" classStyle={styles.icon}>
          <Icon />
        </span>
      )}
      Buy {i}
    </button>
  );
};

// Like the StyleX lane, this uses the per-tab underline fallback and threads full-width
// styles to the li/button because Plumeria does not support descendant selectors.
// Compound states are explicit because simultaneous pseudo-classes are not inferred.
import React, { type ButtonHTMLAttributes, type FunctionComponent, type KeyboardEvent, type ReactNode } from "react";
import * as css from "@plumeria/core";

const desktop = "@media (min-width: 992px)";

const styles = css.create({
  list: {
    position: "relative",
    display: "flex",
    flexWrap: "nowrap",
    gap: 24,
    padding: 0,
    margin: 0,
    overflowX: "auto",
    whiteSpace: "nowrap",
    listStyle: "none",
    scrollbarWidth: "none",
    boxShadow: "inset 0 -1px 0 0 #ddd"
  },
  item: {
    display: "block",
    flexShrink: 0,
    width: "min-content",
    minWidth: 40,
    padding: 0,
    margin: 0
  },
  itemFull: {
    display: "flex",
    flex: 1,
    justifyContent: "center"
  },
  tab: {
    position: "relative",
    display: "inline-flex",
    alignItems: "center",
    height: 40,
    fontSize: 16,
    fontWeight: 400,
    lineHeight: "24px",
    letterSpacing: "0.01em",
    backgroundColor: "transparent",
    borderStyle: "none",
    ":focus-visible": {
      outline: "none"
    },
    "::after": {
      position: "absolute",
      right: 0,
      bottom: 0,
      left: 0,
      content: '""',
      borderBottomStyle: "solid",
      borderBottomWidth: 3,
      transition: "opacity 150ms linear"
    },
    "::before": {
      position: "absolute",
      top: 0,
      bottom: 0,
      width: "100%",
      minWidth: 40,
      height: "100%",
      content: '""'
    },
    [desktop]: {
      fontSize: 14,
      lineHeight: "20px"
    }
  },
  inactive: {
    color: "rgba(0, 0, 0, 0.6)",
    cursor: "pointer",
    ":hover:not(:disabled)": {
      color: "#000"
    },
    ":disabled": {
      color: "rgba(0, 0, 0, 0.26)",
      cursor: "default"
    },
    "::after": {
      borderBottomColor: "transparent"
    },
    ":hover:not(:disabled)::after": {
      borderBottomColor: "#ddd"
    },
    ":focus-visible::after": {
      borderBottomColor: "#007bc7"
    },
  },
  active: {
    color: "#000",
    "::after": {
      borderBottomColor: "#eeb524"
    },
    ":focus-visible::after": {
      borderBottomColor: "#007bc7"
    },
  },
  tabFull: {
    flex: 1
  },
});

const LABELS = ["Overview", "Specs", "Reviews", "Q&A", "Similar", "Deals", "Support", "More"];
interface Group { id: number; count: number; activeIdx: number; fullWidth: boolean; disabledIdx: number; }
interface ITabProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  isActive?: boolean;
  disabled?: boolean;
  fullWidth?: boolean;
}

const Tab: FunctionComponent<ITabProps> = ({ isActive, disabled, fullWidth, ...props }) => (
  <li role="presentation" classStyle={[styles.item, fullWidth && styles.itemFull]}>
    <button
      {...props}
      type="button"
      role="tab"
      disabled={disabled}
      aria-selected={isActive}
      tabIndex={isActive ? 0 : -1}
      classStyle={[styles.tab, isActive ? styles.active : styles.inactive, fullWidth && styles.tabFull]}
    />
  </li>
);

interface ITabsProps {
  children: ReactNode;
}

const Tabs: FunctionComponent<ITabsProps> = ({ children }) => (
  <ul role="tablist" onKeyDown={handleKeyDown} classStyle={styles.list}>
    {children}
  </ul>
);

const FullWidthTabs: FunctionComponent<ITabsProps> = ({ children }) => (
  <ul role="tablist" onKeyDown={handleKeyDown} classStyle={styles.list}>
    {children}
  </ul>
);

// roving-tabindex keyboard navigation (identical behaviour to the styled lane)
const queryTab = (el: Element | null | undefined) => el?.querySelector("button") ?? null;
const firstTab = (list: HTMLUListElement) => queryTab(list.firstElementChild)?.focus();
const lastTab = (list: HTMLUListElement) => queryTab(list.lastElementChild)?.focus();
const nextTab = (list: HTMLUListElement) => {
  const n = queryTab(document.activeElement?.parentElement?.nextElementSibling);
  n ? n.focus() : firstTab(list);
};
const prevTab = (list: HTMLUListElement) => {
  const p = queryTab(document.activeElement?.parentElement?.previousElementSibling);
  p ? p.focus() : lastTab(list);
};
function handleKeyDown(event: KeyboardEvent<HTMLUListElement>) {
  const node = event.currentTarget;
  switch (event.key) {
    case "ArrowRight": nextTab(node); break;
    case "ArrowLeft": prevTab(node); break;
    case "Home": event.preventDefault(); firstTab(node); break;
    case "End": event.preventDefault(); lastTab(node); break;
  }
}

const TabGroup = ({ group }: { group: Group }) => (
  <Tabs>
    {Array.from({ length: group.count }, (_, t) => (
      <Tab
        key={t}
        isActive={t === group.activeIdx}
        disabled={t === group.disabledIdx && t !== group.activeIdx}
      >
        {LABELS[t % LABELS.length]}
      </Tab>
    ))}
  </Tabs>
);

const FullWidthTabGroup = ({ group }: { group: Group }) => (
  <FullWidthTabs>
    {Array.from({ length: group.count }, (_, t) => (
      <Tab
        key={t}
        isActive={t === group.activeIdx}
        disabled={t === group.disabledIdx && t !== group.activeIdx}
        fullWidth
      >
        {LABELS[t % LABELS.length]}
      </Tab>
    ))}
  </FullWidthTabs>
);

export default (i: number) => {
  const count = 3 + (i % 6);
  const g: Group = { id: i, count, activeIdx: i % count, fullWidth: i % 3 === 0, disabledIdx: i % 4 === 0 ? count - 1 : -1 };
  return g.fullWidth ? <FullWidthTabGroup group={g} /> : <TabGroup group={g} />;
};

